SCHEMA_SQL = ("CREATE OR REPLACE FUNCTION public.m3_material_atom()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'pg_catalog', 'public', 'pg_temp'\nAS $function$\nDECLARE r action_receipts; ar agent_runs; pc proposal_prepared_candidates;\n prior category_knowledge_entries;\n expected_type text; identity uuid; latest integer;\n confirmed_proof confirmations; confirmation_required boolean;\n confirmation_xmin xid; receipt_xmin xid; material_xmin xid;\n creation_proof category_creation_confirmations; position_index integer;\n confirmed_item jsonb; expected_content jsonb; expected_refs jsonb; sample_count bigint;\nBEGIN\n SELECT * INTO STRICT r FROM action_receipts WHERE tenant_id=NEW.tenant_id AND id=NEW.receipt_id;\n IF r.category_id IS DISTINCT FROM NEW.category_id OR r.product_id IS NOT NULL\n  OR r.actor_id IS DISTINCT FROM scope_actor() OR r.requester_id IS DISTINCT FROM scope_requester()\n  OR r.run_id IS NOT NULL THEN\n  RAISE EXCEPTION 'material receipt scope mismatch' USING ERRCODE='23514';\n END IF;\n\n -- Row versions must originate in the receipt's transaction, not a later replay.\n SELECT rr.xmin INTO STRICT receipt_xmin FROM action_receipts rr\n  WHERE rr.tenant_id=NEW.tenant_id AND rr.id=r.id;\n EXECUTE format('SELECT xmin FROM public.%I WHERE tenant_id=$1 AND id=$2', TG_TABLE_NAME)\n  INTO STRICT material_xmin USING NEW.tenant_id,NEW.id;\n IF material_xmin IS DISTINCT FROM receipt_xmin THEN\n  RAISE EXCEPTION 'material and receipt must commit together' USING ERRCODE='23514';\n END IF;\n\n confirmation_required=r.operation IN ('category.parameter.publish',\n  'category.knowledge.withdraw','category.knowledge.promote');\n IF TG_TABLE_NAME<>'promotion_proofs' THEN\n  confirmation_required=confirmation_required OR NEW.confirmed_by IS NOT NULL;\n END IF;\n IF confirmation_required THEN\n  -- Fetch the row and transaction identities separately: %ROWTYPE has no xmin.\n  SELECT * INTO STRICT confirmed_proof FROM confirmations cp\n   WHERE cp.tenant_id=NEW.tenant_id AND cp.id=r.confirmation_id;\n  SELECT cp.xmin INTO confirmation_xmin FROM confirmations cp\n   WHERE cp.tenant_id=NEW.tenant_id AND cp.id=r.confirmation_id;\n  IF confirmed_proof.consumed IS DISTINCT FROM true OR confirmed_proof.actor_id<>r.actor_id\n   OR confirmed_proof.category_id IS DISTINCT FROM r.category_id\n   OR confirmed_proof.operation<>r.operation OR confirmed_proof.product_id IS NOT NULL\n   OR confirmation_xmin IS DISTINCT FROM receipt_xmin\n   OR jsonb_typeof(confirmed_proof.snapshot->'payload') IS DISTINCT FROM 'object' THEN\n   RAISE EXCEPTION 'material requires its same-transaction consumed confirmation'\n    USING ERRCODE='23514';\n  END IF;\n ELSE\n  IF r.confirmation_id IS NOT NULL THEN\n   RAISE EXCEPTION 'unconfirmed material cannot borrow a confirmation' USING ERRCODE='23514';\n  END IF;\n END IF;\n IF r.operation='category.create' AND TG_TABLE_NAME IN\n  ('parameter_versions','category_knowledge_entries') THEN\n  SELECT * INTO STRICT creation_proof FROM category_creation_confirmations cp\n   WHERE cp.tenant_id=NEW.tenant_id AND cp.actor_id=r.actor_id\n    AND cp.reserved_category_id=NEW.category_id AND cp.consumed\n    AND cp.payload_digest=r.request_digest;\n  SELECT cp.xmin INTO STRICT confirmation_xmin FROM category_creation_confirmations cp\n   WHERE cp.tenant_id=NEW.tenant_id AND cp.id=creation_proof.id;\n  IF confirmation_xmin IS DISTINCT FROM receipt_xmin\n   OR (SELECT count(*) FROM action_receipts rr WHERE rr.tenant_id=NEW.tenant_id\n       AND rr.category_id=NEW.category_id AND rr.operation='category.create')<>1\n   OR creation_proof.snapshot->'payload'->>'prepared_by_run_id' IS NOT NULL\n   OR creation_proof.snapshot->'payload'->>'candidate_digest' IS NOT NULL\n   OR (creation_proof.snapshot->'payload'->>'deidentified_confirmed')::boolean\n      IS DISTINCT FROM true\n   OR r.subject_type<>'category' OR r.subject_id<>NEW.category_id\n   OR r.subject_revision<>1 OR NEW.version<>1\n   OR r.actor_id<>r.requester_id\n   OR NEW.origin IS DISTINCT FROM (CASE\n    WHEN creation_proof.snapshot->'payload'->>'seed_key' IS NULL THEN 'human' ELSE 'imported' END)\n   OR jsonb_typeof(r.result->'parameters') IS DISTINCT FROM 'array'\n   OR jsonb_typeof(r.result->'knowledge') IS DISTINCT FROM 'array'\n   OR jsonb_typeof(creation_proof.snapshot->'payload'->'groups'->'parameters')\n      IS DISTINCT FROM 'array'\n   OR jsonb_typeof(creation_proof.snapshot->'payload'->'groups'->'knowledge')\n      IS DISTINCT FROM 'array' THEN\n   RAISE EXCEPTION 'category material creation proof mismatch' USING ERRCODE='23514';\n  END IF;\n  IF jsonb_array_length(r.result->'parameters')<>\n      jsonb_array_length(creation_proof.snapshot->'payload'->'groups'->'parameters')\n   OR jsonb_array_length(r.result->'knowledge')<>\n      jsonb_array_length(creation_proof.snapshot->'payload'->'groups'->'knowledge')\n   OR jsonb_array_length(r.result->'parameters')<>(SELECT count(*) FROM parameter_versions v\n      WHERE v.tenant_id=NEW.tenant_id AND v.category_id=NEW.category_id AND v.receipt_id=r.id)\n   OR jsonb_array_length(r.result->'knowledge')<>(SELECT count(*) FROM category_knowledge_entries k\n      WHERE k.tenant_id=NEW.tenant_id AND k.category_id=NEW.category_id AND k.receipt_id=r.id) THEN\n   RAISE EXCEPTION 'category initial material manifest is incomplete' USING ERRCODE='23514';\n  END IF;\n  IF TG_TABLE_NAME='parameter_versions' THEN\n   SELECT (m.ordinality-1)::integer INTO STRICT position_index\n    FROM jsonb_array_elements(r.result->'parameters') WITH ORDINALITY m(item,ordinality)\n    WHERE m.item->>'parameter_id'=NEW.parameter_id::text\n     AND m.item->>'key'=NEW.key AND (m.item->>'version')::integer=NEW.version;\n   confirmed_item=creation_proof.snapshot->'payload'->'groups'->'parameters'->position_index;\n   IF (to_jsonb(NEW)-ARRAY['id','tenant_id','category_id','created_at','parameter_id','version',\n        'replaces_version','origin','writer_id','run_id','confirmed_by','receipt_id',\n        'prepared_candidate_id']) IS DISTINCT FROM confirmed_item THEN\n    RAISE EXCEPTION 'initial parameter differs from confirmed content' USING ERRCODE='23514';\n   END IF;\n  ELSE\n   SELECT (m.ordinality-1)::integer INTO STRICT position_index\n    FROM jsonb_array_elements(r.result->'knowledge') WITH ORDINALITY m(item,ordinality)\n    WHERE m.item->>'entry_id'=NEW.id::text AND m.item->>'lineage_id'=NEW.lineage_id::text\n     AND (m.item->>'version')::integer=NEW.version;\n   confirmed_item=creation_proof.snapshot->'payload'->'groups'->'knowledge'->position_index;\n   expected_content=confirmed_item->'content';\n   expected_refs=confirmed_item->'source_refs';\n   IF confirmed_item->>'kind'='voice' THEN\n    expected_refs=expected_refs||(expected_content->'representative_refs');\n    SELECT count(DISTINCT ROW(ref->>'id',ref->>'version',ref->>'line'))\n     INTO sample_count FROM jsonb_array_elements(expected_refs) ref;\n    expected_content=expected_content||jsonb_build_object('sample_size',sample_count);\n   ELSIF confirmed_item->>'kind'='competitor' THEN\n    SELECT expected_refs||coalesce(jsonb_agg(entry->'source_ref' ORDER BY ordinality), '[]'::jsonb)\n     INTO expected_refs FROM jsonb_array_elements(\n      (expected_content->'metrics')||(expected_content->'features')||(expected_content->'prices'))\n      WITH ORDINALITY refs(entry,ordinality)\n      WHERE jsonb_typeof(entry->'source_ref')='object';\n   END IF;\n   IF NEW.kind IS DISTINCT FROM confirmed_item->>'kind'\n    OR NEW.content IS DISTINCT FROM expected_content\n    OR to_jsonb(NEW.regions) IS DISTINCT FROM confirmed_item->'regions'\n    OR NEW.source_refs IS DISTINCT FROM expected_refs\n    OR NEW.action<>'add' OR NEW.withdraw_reason IS NOT NULL THEN\n    RAISE EXCEPTION 'initial knowledge differs from confirmed content' USING ERRCODE='23514';\n   END IF;\n  END IF;\n END IF;\n IF TG_TABLE_NAME='promotion_proofs' THEN\n  IF NEW.id::text IS DISTINCT FROM r.result->>'promotion_proof_id'\n   OR confirmed_proof.subject_type<>'proposal'\n   OR confirmed_proof.subject_id<>NEW.source_proposal_id\n   OR confirmed_proof.revision<>NEW.source_proposal_revision\n   OR (confirmed_proof.snapshot->'payload'->>'source_proposal_id')::uuid\n      IS DISTINCT FROM NEW.source_proposal_id\n   OR (confirmed_proof.snapshot->'payload'->>'source_proposal_revision')::integer\n      IS DISTINCT FROM NEW.source_proposal_revision\n   OR confirmed_proof.snapshot->'payload'->'source_item_refs' IS DISTINCT FROM NEW.source_item_refs\n   OR (confirmed_proof.snapshot->'payload'->>'deidentified_confirmed')::boolean IS DISTINCT FROM true\n   OR r.operation<>'category.knowledge.promote' OR r.actor_id<>NEW.deidentified_by\n   OR r.actor_id<>r.requester_id OR NOT EXISTS(SELECT 1 FROM principals p\n    WHERE p.tenant_id=NEW.tenant_id AND p.id=NEW.deidentified_by AND p.kind='human')\n   OR NOT EXISTS(SELECT 1 FROM category_knowledge_entries k WHERE k.tenant_id=NEW.tenant_id\n    AND k.category_id=NEW.category_id AND k.id=NEW.knowledge_entry_id AND k.receipt_id=r.id\n    AND r.subject_type='category_knowledge' AND r.subject_id=k.lineage_id\n    AND r.subject_revision=k.version)\n   OR NOT EXISTS(SELECT 1 FROM proposal_revisions pv WHERE pv.tenant_id=NEW.tenant_id\n    AND pv.category_id=NEW.category_id AND pv.proposal_id=NEW.source_proposal_id\n    AND pv.revision=NEW.source_proposal_revision)\n   OR NOT coalesce((NEW.checks->>'refs_clean')::boolean,false)\n   OR NOT coalesce((NEW.checks->>'filenames_clean')::boolean,false)\n   OR NOT coalesce((NEW.checks->>'identities_clean')::boolean,false) THEN\n   RAISE EXCEPTION 'promotion proof does not bind the named receipt' USING ERRCODE='23514';\n  END IF;\n  RETURN NULL;\n END IF;\n IF TG_TABLE_NAME='parameter_versions' THEN\n  expected_type='parameter'; identity=NEW.parameter_id;\n  IF r.operation NOT IN ('category.parameter.publish','category.create') THEN\n   RAISE EXCEPTION 'parameter receipt operation mismatch' USING ERRCODE='23514';\n  END IF;\n  SELECT max(version) INTO latest FROM parameter_versions WHERE tenant_id=NEW.tenant_id\n   AND parameter_id=NEW.parameter_id;\n  IF NOT EXISTS(SELECT 1 FROM parameter_current c WHERE c.tenant_id=NEW.tenant_id\n   AND c.category_id=NEW.category_id AND c.parameter_id=NEW.parameter_id\n   AND c.key=NEW.key AND c.current_version=latest)\n   OR (NEW.version=1 AND NEW.replaces_version IS NOT NULL)\n   OR (NEW.version>1 AND (NEW.replaces_version IS DISTINCT FROM NEW.version-1\n    OR NOT EXISTS(SELECT 1 FROM parameter_versions v WHERE v.tenant_id=NEW.tenant_id\n     AND v.category_id=NEW.category_id AND v.parameter_id=NEW.parameter_id\n     AND v.version=NEW.version-1 AND v.key=NEW.key))) THEN\n   RAISE EXCEPTION 'parameter version and current must commit together' USING ERRCODE='23514';\n  END IF;\n ELSE\n  expected_type='category_knowledge'; identity=NEW.lineage_id;\n  IF r.operation NOT IN ('category.knowledge.add','category.knowledge.withdraw',\n   'category.knowledge.promote','category.create')\n   OR (NEW.action='withdraw') IS DISTINCT FROM (r.operation='category.knowledge.withdraw') THEN\n   RAISE EXCEPTION 'knowledge receipt operation mismatch' USING ERRCODE='23514';\n  END IF;\n  SELECT max(version) INTO latest FROM category_knowledge_entries WHERE tenant_id=NEW.tenant_id\n   AND lineage_id=NEW.lineage_id;\n  IF NOT EXISTS(SELECT 1 FROM category_knowledge_current c WHERE c.tenant_id=NEW.tenant_id\n   AND c.category_id=NEW.category_id AND c.lineage_id=NEW.lineage_id AND c.current_version=latest)\n   OR (NEW.version=1 AND NEW.action<>'add') THEN\n   RAISE EXCEPTION 'knowledge entry and current must commit together' USING ERRCODE='23514';\n  END IF;\n  IF NEW.version>1 THEN\n   SELECT * INTO STRICT prior FROM category_knowledge_entries WHERE tenant_id=NEW.tenant_id\n    AND category_id=NEW.category_id AND lineage_id=NEW.lineage_id AND version=NEW.version-1;\n   IF NEW.kind<>prior.kind OR NEW.action='add' THEN\n    RAISE EXCEPTION 'knowledge lineage mismatch' USING ERRCODE='23514';\n   END IF;\n  END IF;\n  IF r.operation='category.knowledge.promote' AND NOT EXISTS(SELECT 1 FROM promotion_proofs p\n   WHERE p.tenant_id=NEW.tenant_id AND p.knowledge_entry_id=NEW.id AND p.receipt_id=r.id) THEN\n   RAISE EXCEPTION 'promotion requires its private proof' USING ERRCODE='23514';\n  END IF;\n END IF;\n IF NOT ((r.subject_type=expected_type AND r.subject_id=identity AND r.subject_revision=NEW.version)\n  OR (r.operation='category.create' AND r.subject_type='category'\n   AND r.subject_id=NEW.category_id AND NEW.version=1)) THEN\n  RAISE EXCEPTION 'material receipt subject mismatch' USING ERRCODE='23514';\n END IF;\n\n IF confirmation_required THEN\n  confirmed_item=confirmed_proof.snapshot->'payload';\n  IF TG_TABLE_NAME='parameter_versions' THEN\n   IF (to_jsonb(NEW)-ARRAY['id','tenant_id','category_id','created_at','parameter_id','version',\n        'replaces_version','origin','writer_id','run_id','confirmed_by','receipt_id',\n        'prepared_candidate_id']) IS DISTINCT FROM\n       (confirmed_item-ARRAY['parameter_id','expected_current_version','prepared_by_run_id',\n                            'candidate_digest'])\n    OR (confirmed_item->>'expected_current_version')::integer IS DISTINCT FROM NEW.version-1\n    OR (NEW.version=1 AND confirmed_item->>'parameter_id' IS NOT NULL)\n    OR (NEW.version>1 AND (confirmed_item->>'parameter_id')::uuid\n        IS DISTINCT FROM NEW.parameter_id)\n    OR (NEW.version=1 AND (confirmed_proof.subject_type<>'category'\n         OR confirmed_proof.subject_id<>NEW.category_id))\n    OR (NEW.version>1 AND (confirmed_proof.subject_type<>'parameter'\n         OR confirmed_proof.subject_id<>NEW.parameter_id\n         OR confirmed_proof.revision<>NEW.version-1)) THEN\n    RAISE EXCEPTION 'published parameter differs from confirmation' USING ERRCODE='23514';\n   END IF;\n  ELSIF r.operation='category.knowledge.withdraw' THEN\n   IF (confirmed_item->>'lineage_id')::uuid IS DISTINCT FROM NEW.lineage_id\n    OR (confirmed_item->>'expected_version')::integer IS DISTINCT FROM NEW.version-1\n    OR confirmed_item->>'reason' IS DISTINCT FROM NEW.withdraw_reason\n    OR coalesce(length(NEW.withdraw_reason),0)=0\n    OR confirmed_proof.subject_type<>'category_knowledge'\n    OR confirmed_proof.subject_id<>NEW.lineage_id OR confirmed_proof.revision<>NEW.version-1\n    OR NEW.content IS DISTINCT FROM prior.content OR NEW.regions IS DISTINCT FROM prior.regions\n    OR NEW.source_refs IS DISTINCT FROM prior.source_refs THEN\n    RAISE EXCEPTION 'knowledge withdrawal differs from confirmation or prior version'\n     USING ERRCODE='23514';\n   END IF;\n  ELSE\n   expected_content=confirmed_item->'content';\n   expected_refs=coalesce(confirmed_item->'source_refs','[]'::jsonb);\n   IF confirmed_item->>'kind'='voice' THEN\n    expected_refs=expected_refs||(expected_content->'representative_refs');\n    SELECT count(DISTINCT ROW(ref->>'id',ref->>'version',ref->>'line'))\n     INTO sample_count FROM jsonb_array_elements(expected_refs) ref;\n    expected_content=expected_content||jsonb_build_object('sample_size',sample_count);\n   ELSIF confirmed_item->>'kind'='competitor' THEN\n    SELECT expected_refs||coalesce(jsonb_agg(entry->'source_ref' ORDER BY ordinality), '[]'::jsonb)\n     INTO expected_refs FROM jsonb_array_elements(\n      (expected_content->'metrics')||(expected_content->'features')||(expected_content->'prices'))\n      WITH ORDINALITY refs(entry,ordinality)\n      WHERE jsonb_typeof(entry->'source_ref')='object';\n   END IF;\n   IF r.operation='category.knowledge.promote' THEN\n    expected_refs='[]'::jsonb;\n    IF NEW.version<>1 OR NEW.action<>'add' OR confirmed_proof.subject_type<>'proposal'\n     OR confirmed_proof.subject_id IS DISTINCT FROM (confirmed_item->>'source_proposal_id')::uuid\n     OR confirmed_proof.revision IS DISTINCT FROM\n        (confirmed_item->>'source_proposal_revision')::integer\n     OR (confirmed_item->>'deidentified_confirmed')::boolean IS DISTINCT FROM true THEN\n     RAISE EXCEPTION 'promoted knowledge differs from confirmed source' USING ERRCODE='23514';\n    END IF;\n   ELSE\n    IF (NEW.version=1 AND (confirmed_item->>'supersedes' IS NOT NULL\n         OR confirmed_proof.subject_type<>'category'\n         OR confirmed_proof.subject_id<>NEW.category_id))\n     OR (NEW.version>1 AND (\n         (confirmed_item->'supersedes'->>'lineage_id')::uuid IS DISTINCT FROM NEW.lineage_id\n         OR (confirmed_item->'supersedes'->>'expected_version')::integer\n            IS DISTINCT FROM NEW.version-1\n         OR confirmed_proof.subject_type<>'category_knowledge'\n         OR confirmed_proof.subject_id<>NEW.lineage_id OR confirmed_proof.revision<>NEW.version-1)) THEN\n     RAISE EXCEPTION 'knowledge supersession differs from confirmation' USING ERRCODE='23514';\n    END IF;\n   END IF;\n   IF NEW.kind IS DISTINCT FROM confirmed_item->>'kind'\n    OR NEW.content IS DISTINCT FROM expected_content OR NEW.source_refs IS DISTINCT FROM expected_refs\n    OR to_jsonb(NEW.regions) IS DISTINCT FROM coalesce(confirmed_item->'regions','[]'::jsonb)\n    OR NEW.withdraw_reason IS NOT NULL THEN\n    RAISE EXCEPTION 'knowledge content differs from confirmation' USING ERRCODE='23514';\n   END IF;\n  END IF;\n END IF;\n IF NEW.origin='human' OR (NEW.origin='imported' AND r.operation='category.create') THEN\n  IF NEW.writer_id<>r.actor_id OR r.actor_id<>r.requester_id\n   OR NEW.run_id IS NOT NULL OR NEW.confirmed_by IS NOT NULL\n   OR NEW.prepared_candidate_id IS NOT NULL OR r.agent_run_id IS NOT NULL\n   OR (confirmation_required AND (\n    confirmed_proof.snapshot->'payload'->>'prepared_by_run_id' IS NOT NULL\n    OR confirmed_proof.snapshot->'payload'->>'candidate_digest' IS NOT NULL))\n   OR NOT EXISTS(SELECT 1 FROM principals p WHERE p.tenant_id=NEW.tenant_id\n    AND p.id=NEW.writer_id AND p.kind='human') THEN\n   RAISE EXCEPTION 'material human provenance mismatch' USING ERRCODE='23514';\n  END IF;\n ELSIF NEW.origin='ai_draft' THEN\n  SELECT * INTO STRICT ar FROM agent_runs WHERE tenant_id=NEW.tenant_id AND id=NEW.run_id;\n  IF ar.category_id IS DISTINCT FROM NEW.category_id OR ar.writer_id<>NEW.writer_id\n   OR ar.requester_id<>r.requester_id OR ar.reverted_at IS NOT NULL OR ar.state='cancelled'\n   OR r.agent_run_id IS DISTINCT FROM ar.id OR ar.product_id IS NOT NULL\n   OR NOT EXISTS(SELECT 1 FROM principals p WHERE p.tenant_id=NEW.tenant_id\n    AND p.id=NEW.writer_id AND p.kind='agent') THEN\n   RAISE EXCEPTION 'material AI provenance mismatch' USING ERRCODE='23514';\n  END IF;\n  IF r.operation='category.knowledge.add' AND ar.private_context THEN\n   RAISE EXCEPTION 'private run cannot add shared knowledge' USING ERRCODE='23514';\n  END IF;\n  IF NEW.confirmed_by IS NULL THEN\n   IF r.operation<>'category.knowledge.add' OR r.actor_id<>ar.writer_id\n    OR NEW.prepared_candidate_id IS NOT NULL\n    OR (NEW.version>1 AND (prior.origin<>'ai_draft' OR prior.confirmed_by IS NOT NULL))\n    OR NOT EXISTS(SELECT 1 FROM agent_tool_calls tc WHERE tc.tenant_id=NEW.tenant_id\n     AND tc.run_id=ar.id AND tc.receipt_id=r.id AND tc.state='completed'\n     AND tc.execution_binding->>'operation'=r.operation) THEN\n    RAISE EXCEPTION 'material T0 requires its trusted call' USING ERRCODE='23514';\n   END IF;\n  ELSE\n   SELECT * INTO STRICT pc FROM proposal_prepared_candidates WHERE tenant_id=NEW.tenant_id\n    AND id=NEW.prepared_candidate_id;\n   IF NEW.confirmed_by<>r.actor_id OR r.actor_id<>r.requester_id\n    OR pc.category_id<>NEW.category_id OR pc.run_id<>ar.id OR pc.writer_id<>ar.writer_id\n    OR pc.requester_id<>r.requester_id OR pc.operation<>r.operation\n    OR ((confirmed_proof.snapshot->'payload')-ARRAY['prepared_by_run_id','candidate_digest'])\n       IS DISTINCT FROM pc.payload\n    OR confirmed_proof.snapshot->'payload'->>'prepared_by_run_id' IS DISTINCT FROM ar.id::text\n    OR confirmed_proof.snapshot->'payload'->>'candidate_digest' IS DISTINCT FROM pc.candidate_digest\n    OR (pc.execution_binding->'model'->>'cancel_epoch')::integer IS DISTINCT FROM ar.cancel_epoch\n    OR NOT EXISTS(SELECT 1 FROM principals p WHERE p.tenant_id=NEW.tenant_id\n     AND p.id=NEW.confirmed_by AND p.kind='human') THEN\n    RAISE EXCEPTION 'material candidate confirmation mismatch' USING ERRCODE='23514';\n   END IF;\n  END IF;\n ELSE\n  RAISE EXCEPTION 'material import requires a registered import path' USING ERRCODE='23514';\n END IF;\n RETURN NULL;\nEND $function$\n",)

DOWNGRADE_SQL = ("CREATE OR REPLACE FUNCTION public.m3_material_atom()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'pg_catalog', 'public', 'pg_temp'\nAS $function$\nDECLARE r action_receipts; ar agent_runs; pc proposal_prepared_candidates;\n prior category_knowledge_entries;\n expected_type text; identity uuid; latest integer;\n confirmed_proof confirmations; confirmation_required boolean;\n confirmation_xmin xid; receipt_xmin xid; material_xmin xid;\n creation_proof category_creation_confirmations; position_index integer;\n confirmed_item jsonb; expected_content jsonb; expected_refs jsonb; sample_count bigint;\nBEGIN\n SELECT * INTO STRICT r FROM action_receipts WHERE tenant_id=NEW.tenant_id AND id=NEW.receipt_id;\n IF r.category_id IS DISTINCT FROM NEW.category_id OR r.product_id IS NOT NULL\n  OR r.actor_id IS DISTINCT FROM scope_actor() OR r.requester_id IS DISTINCT FROM scope_requester()\n  OR r.run_id IS NOT NULL THEN\n  RAISE EXCEPTION 'material receipt scope mismatch' USING ERRCODE='23514';\n END IF;\n\n -- Row versions must originate in the receipt's transaction, not a later replay.\n SELECT rr.xmin INTO STRICT receipt_xmin FROM action_receipts rr\n  WHERE rr.tenant_id=NEW.tenant_id AND rr.id=r.id;\n EXECUTE format('SELECT xmin FROM public.%I WHERE tenant_id=$1 AND id=$2', TG_TABLE_NAME)\n  INTO STRICT material_xmin USING NEW.tenant_id,NEW.id;\n IF material_xmin IS DISTINCT FROM receipt_xmin THEN\n  RAISE EXCEPTION 'material and receipt must commit together' USING ERRCODE='23514';\n END IF;\n\n confirmation_required=r.operation IN ('category.parameter.publish',\n  'category.knowledge.withdraw','category.knowledge.promote');\n IF TG_TABLE_NAME<>'promotion_proofs' THEN\n  confirmation_required=confirmation_required OR NEW.confirmed_by IS NOT NULL;\n END IF;\n IF confirmation_required THEN\n  -- Fetch the row and transaction identities separately: %ROWTYPE has no xmin.\n  SELECT * INTO STRICT confirmed_proof FROM confirmations cp\n   WHERE cp.tenant_id=NEW.tenant_id AND cp.id=r.confirmation_id;\n  SELECT cp.xmin INTO confirmation_xmin FROM confirmations cp\n   WHERE cp.tenant_id=NEW.tenant_id AND cp.id=r.confirmation_id;\n  IF confirmed_proof.consumed IS DISTINCT FROM true OR confirmed_proof.actor_id<>r.actor_id\n   OR confirmed_proof.category_id IS DISTINCT FROM r.category_id\n   OR confirmed_proof.operation<>r.operation OR confirmed_proof.product_id IS NOT NULL\n   OR confirmation_xmin IS DISTINCT FROM receipt_xmin\n   OR jsonb_typeof(confirmed_proof.snapshot->'payload') IS DISTINCT FROM 'object' THEN\n   RAISE EXCEPTION 'material requires its same-transaction consumed confirmation'\n    USING ERRCODE='23514';\n  END IF;\n ELSE\n  IF r.confirmation_id IS NOT NULL THEN\n   RAISE EXCEPTION 'unconfirmed material cannot borrow a confirmation' USING ERRCODE='23514';\n  END IF;\n END IF;\n IF r.operation='category.create' AND TG_TABLE_NAME IN\n  ('parameter_versions','category_knowledge_entries') THEN\n  SELECT * INTO STRICT creation_proof FROM category_creation_confirmations cp\n   WHERE cp.tenant_id=NEW.tenant_id AND cp.actor_id=r.actor_id\n    AND cp.reserved_category_id=NEW.category_id AND cp.consumed\n    AND cp.payload_digest=r.request_digest;\n  SELECT cp.xmin INTO STRICT confirmation_xmin FROM category_creation_confirmations cp\n   WHERE cp.tenant_id=NEW.tenant_id AND cp.id=creation_proof.id;\n  IF confirmation_xmin IS DISTINCT FROM receipt_xmin\n   OR (SELECT count(*) FROM action_receipts rr WHERE rr.tenant_id=NEW.tenant_id\n       AND rr.category_id=NEW.category_id AND rr.operation='category.create')<>1\n   OR creation_proof.snapshot->'payload'->>'prepared_by_run_id' IS NOT NULL\n   OR creation_proof.snapshot->'payload'->>'candidate_digest' IS NOT NULL\n   OR (creation_proof.snapshot->'payload'->>'deidentified_confirmed')::boolean\n      IS DISTINCT FROM true\n   OR r.subject_type<>'category' OR r.subject_id<>NEW.category_id\n   OR r.subject_revision<>1 OR NEW.version<>1\n   OR r.actor_id<>r.requester_id\n   OR NEW.origin IS DISTINCT FROM (CASE\n    WHEN creation_proof.snapshot->'payload'->>'seed_key' IS NULL THEN 'human' ELSE 'imported' END)\n   OR jsonb_typeof(r.result->'parameters') IS DISTINCT FROM 'array'\n   OR jsonb_typeof(r.result->'knowledge') IS DISTINCT FROM 'array'\n   OR jsonb_typeof(creation_proof.snapshot->'payload'->'groups'->'parameters')\n      IS DISTINCT FROM 'array'\n   OR jsonb_typeof(creation_proof.snapshot->'payload'->'groups'->'knowledge')\n      IS DISTINCT FROM 'array' THEN\n   RAISE EXCEPTION 'category material creation proof mismatch' USING ERRCODE='23514';\n  END IF;\n  IF jsonb_array_length(r.result->'parameters')<>\n      jsonb_array_length(creation_proof.snapshot->'payload'->'groups'->'parameters')\n   OR jsonb_array_length(r.result->'knowledge')<>\n      jsonb_array_length(creation_proof.snapshot->'payload'->'groups'->'knowledge')\n   OR jsonb_array_length(r.result->'parameters')<>(SELECT count(*) FROM parameter_versions v\n      WHERE v.tenant_id=NEW.tenant_id AND v.category_id=NEW.category_id AND v.receipt_id=r.id)\n   OR jsonb_array_length(r.result->'knowledge')<>(SELECT count(*) FROM category_knowledge_entries k\n      WHERE k.tenant_id=NEW.tenant_id AND k.category_id=NEW.category_id AND k.receipt_id=r.id) THEN\n   RAISE EXCEPTION 'category initial material manifest is incomplete' USING ERRCODE='23514';\n  END IF;\n  IF TG_TABLE_NAME='parameter_versions' THEN\n   SELECT (m.ordinality-1)::integer INTO STRICT position_index\n    FROM jsonb_array_elements(r.result->'parameters') WITH ORDINALITY m(item,ordinality)\n    WHERE m.item->>'parameter_id'=NEW.parameter_id::text\n     AND m.item->>'key'=NEW.key AND (m.item->>'version')::integer=NEW.version;\n   confirmed_item=creation_proof.snapshot->'payload'->'groups'->'parameters'->position_index;\n   IF (to_jsonb(NEW)-ARRAY['id','tenant_id','category_id','created_at','parameter_id','version',\n        'replaces_version','origin','writer_id','run_id','confirmed_by','receipt_id',\n        'prepared_candidate_id']) IS DISTINCT FROM confirmed_item THEN\n    RAISE EXCEPTION 'initial parameter differs from confirmed content' USING ERRCODE='23514';\n   END IF;\n  ELSE\n   SELECT (m.ordinality-1)::integer INTO STRICT position_index\n    FROM jsonb_array_elements(r.result->'knowledge') WITH ORDINALITY m(item,ordinality)\n    WHERE m.item->>'entry_id'=NEW.id::text AND m.item->>'lineage_id'=NEW.lineage_id::text\n     AND (m.item->>'version')::integer=NEW.version;\n   confirmed_item=creation_proof.snapshot->'payload'->'groups'->'knowledge'->position_index;\n   expected_content=confirmed_item->'content';\n   expected_refs=confirmed_item->'source_refs';\n   IF confirmed_item->>'kind'='voice' THEN\n    expected_refs=expected_refs||(expected_content->'representative_refs');\n    SELECT count(DISTINCT ROW(ref->>'id',ref->>'version',ref->>'line'))\n     INTO sample_count FROM jsonb_array_elements(expected_refs) ref;\n    expected_content=expected_content||jsonb_build_object('sample_size',sample_count);\n   ELSIF confirmed_item->>'kind'='competitor' THEN\n    SELECT expected_refs||coalesce(jsonb_agg(entry->'source_ref' ORDER BY ordinality), '[]'::jsonb)\n     INTO expected_refs FROM jsonb_array_elements(\n      (expected_content->'metrics')||(expected_content->'features')||(expected_content->'prices'))\n      WITH ORDINALITY refs(entry,ordinality)\n      WHERE jsonb_typeof(entry->'source_ref')='object';\n   END IF;\n   IF NEW.kind IS DISTINCT FROM confirmed_item->>'kind'\n    OR NEW.content IS DISTINCT FROM expected_content\n    OR to_jsonb(NEW.regions) IS DISTINCT FROM confirmed_item->'regions'\n    OR NEW.source_refs IS DISTINCT FROM expected_refs\n    OR NEW.action<>'add' OR NEW.withdraw_reason IS NOT NULL THEN\n    RAISE EXCEPTION 'initial knowledge differs from confirmed content' USING ERRCODE='23514';\n   END IF;\n  END IF;\n END IF;\n IF TG_TABLE_NAME='promotion_proofs' THEN\n  IF NEW.id::text IS DISTINCT FROM r.result->>'promotion_proof_id'\n   OR confirmed_proof.subject_type<>'proposal'\n   OR confirmed_proof.subject_id<>NEW.source_proposal_id\n   OR confirmed_proof.revision<>NEW.source_proposal_revision\n   OR (confirmed_proof.snapshot->'payload'->>'source_proposal_id')::uuid\n      IS DISTINCT FROM NEW.source_proposal_id\n   OR (confirmed_proof.snapshot->'payload'->>'source_proposal_revision')::integer\n      IS DISTINCT FROM NEW.source_proposal_revision\n   OR confirmed_proof.snapshot->'payload'->'source_item_refs' IS DISTINCT FROM NEW.source_item_refs\n   OR (confirmed_proof.snapshot->'payload'->>'deidentified_confirmed')::boolean IS DISTINCT FROM true\n   OR r.operation<>'category.knowledge.promote' OR r.actor_id<>NEW.deidentified_by\n   OR r.actor_id<>r.requester_id OR NOT EXISTS(SELECT 1 FROM principals p\n    WHERE p.tenant_id=NEW.tenant_id AND p.id=NEW.deidentified_by AND p.kind='human')\n   OR NOT EXISTS(SELECT 1 FROM category_knowledge_entries k WHERE k.tenant_id=NEW.tenant_id\n    AND k.category_id=NEW.category_id AND k.id=NEW.knowledge_entry_id AND k.receipt_id=r.id\n    AND r.subject_type='category_knowledge' AND r.subject_id=k.lineage_id\n    AND r.subject_revision=k.version)\n   OR NOT EXISTS(SELECT 1 FROM proposal_revisions pv WHERE pv.tenant_id=NEW.tenant_id\n    AND pv.category_id=NEW.category_id AND pv.proposal_id=NEW.source_proposal_id\n    AND pv.revision=NEW.source_proposal_revision)\n   OR NOT coalesce((NEW.checks->>'refs_clean')::boolean,false)\n   OR NOT coalesce((NEW.checks->>'filenames_clean')::boolean,false)\n   OR NOT coalesce((NEW.checks->>'identities_clean')::boolean,false) THEN\n   RAISE EXCEPTION 'promotion proof does not bind the named receipt' USING ERRCODE='23514';\n  END IF;\n  RETURN NULL;\n END IF;\n IF TG_TABLE_NAME='parameter_versions' THEN\n  expected_type='parameter'; identity=NEW.parameter_id;\n  IF r.operation NOT IN ('category.parameter.publish','category.create') THEN\n   RAISE EXCEPTION 'parameter receipt operation mismatch' USING ERRCODE='23514';\n  END IF;\n  SELECT max(version) INTO latest FROM parameter_versions WHERE tenant_id=NEW.tenant_id\n   AND parameter_id=NEW.parameter_id;\n  IF NOT EXISTS(SELECT 1 FROM parameter_current c WHERE c.tenant_id=NEW.tenant_id\n   AND c.category_id=NEW.category_id AND c.parameter_id=NEW.parameter_id\n   AND c.key=NEW.key AND c.current_version=latest)\n   OR (NEW.version=1 AND NEW.replaces_version IS NOT NULL)\n   OR (NEW.version>1 AND (NEW.replaces_version IS DISTINCT FROM NEW.version-1\n    OR NOT EXISTS(SELECT 1 FROM parameter_versions v WHERE v.tenant_id=NEW.tenant_id\n     AND v.category_id=NEW.category_id AND v.parameter_id=NEW.parameter_id\n     AND v.version=NEW.version-1 AND v.key=NEW.key))) THEN\n   RAISE EXCEPTION 'parameter version and current must commit together' USING ERRCODE='23514';\n  END IF;\n ELSE\n  expected_type='category_knowledge'; identity=NEW.lineage_id;\n  IF r.operation NOT IN ('category.knowledge.add','category.knowledge.withdraw',\n   'category.knowledge.promote','category.create')\n   OR (NEW.action='withdraw') IS DISTINCT FROM (r.operation='category.knowledge.withdraw') THEN\n   RAISE EXCEPTION 'knowledge receipt operation mismatch' USING ERRCODE='23514';\n  END IF;\n  SELECT max(version) INTO latest FROM category_knowledge_entries WHERE tenant_id=NEW.tenant_id\n   AND lineage_id=NEW.lineage_id;\n  IF NOT EXISTS(SELECT 1 FROM category_knowledge_current c WHERE c.tenant_id=NEW.tenant_id\n   AND c.category_id=NEW.category_id AND c.lineage_id=NEW.lineage_id AND c.current_version=latest)\n   OR (NEW.version=1 AND NEW.action<>'add') THEN\n   RAISE EXCEPTION 'knowledge entry and current must commit together' USING ERRCODE='23514';\n  END IF;\n  IF NEW.version>1 THEN\n   SELECT * INTO STRICT prior FROM category_knowledge_entries WHERE tenant_id=NEW.tenant_id\n    AND category_id=NEW.category_id AND lineage_id=NEW.lineage_id AND version=NEW.version-1;\n   IF NEW.kind<>prior.kind OR NEW.action='add' THEN\n    RAISE EXCEPTION 'knowledge lineage mismatch' USING ERRCODE='23514';\n   END IF;\n  END IF;\n  IF r.operation='category.knowledge.promote' AND NOT EXISTS(SELECT 1 FROM promotion_proofs p\n   WHERE p.tenant_id=NEW.tenant_id AND p.knowledge_entry_id=NEW.id AND p.receipt_id=r.id) THEN\n   RAISE EXCEPTION 'promotion requires its private proof' USING ERRCODE='23514';\n  END IF;\n END IF;\n IF NOT ((r.subject_type=expected_type AND r.subject_id=identity AND r.subject_revision=NEW.version)\n  OR (r.operation='category.create' AND r.subject_type='category'\n   AND r.subject_id=NEW.category_id AND NEW.version=1)) THEN\n  RAISE EXCEPTION 'material receipt subject mismatch' USING ERRCODE='23514';\n END IF;\n\n IF confirmation_required THEN\n  confirmed_item=confirmed_proof.snapshot->'payload';\n  IF TG_TABLE_NAME='parameter_versions' THEN\n   IF (to_jsonb(NEW)-ARRAY['id','tenant_id','category_id','created_at','parameter_id','version',\n        'replaces_version','origin','writer_id','run_id','confirmed_by','receipt_id',\n        'prepared_candidate_id']) IS DISTINCT FROM\n       (confirmed_item-ARRAY['parameter_id','expected_current_version','prepared_by_run_id',\n                            'candidate_digest'])\n    OR (confirmed_item->>'expected_current_version')::integer IS DISTINCT FROM NEW.version-1\n    OR (NEW.version=1 AND confirmed_item->>'parameter_id' IS NOT NULL)\n    OR (NEW.version>1 AND (confirmed_item->>'parameter_id')::uuid\n        IS DISTINCT FROM NEW.parameter_id)\n    OR (NEW.version=1 AND (confirmed_proof.subject_type<>'category'\n         OR confirmed_proof.subject_id<>NEW.category_id))\n    OR (NEW.version>1 AND (confirmed_proof.subject_type<>'parameter'\n         OR confirmed_proof.subject_id<>NEW.parameter_id\n         OR confirmed_proof.revision<>NEW.version-1)) THEN\n    RAISE EXCEPTION 'published parameter differs from confirmation' USING ERRCODE='23514';\n   END IF;\n  ELSIF r.operation='category.knowledge.withdraw' THEN\n   IF (confirmed_item->>'lineage_id')::uuid IS DISTINCT FROM NEW.lineage_id\n    OR (confirmed_item->>'expected_version')::integer IS DISTINCT FROM NEW.version-1\n    OR confirmed_item->>'reason' IS DISTINCT FROM NEW.withdraw_reason\n    OR coalesce(length(NEW.withdraw_reason),0)=0\n    OR confirmed_proof.subject_type<>'category_knowledge'\n    OR confirmed_proof.subject_id<>NEW.lineage_id OR confirmed_proof.revision<>NEW.version-1\n    OR NEW.content IS DISTINCT FROM prior.content OR NEW.regions IS DISTINCT FROM prior.regions\n    OR NEW.source_refs IS DISTINCT FROM prior.source_refs THEN\n    RAISE EXCEPTION 'knowledge withdrawal differs from confirmation or prior version'\n     USING ERRCODE='23514';\n   END IF;\n  ELSE\n   expected_content=confirmed_item->'content';\n   expected_refs=coalesce(confirmed_item->'source_refs','[]'::jsonb);\n   IF confirmed_item->>'kind'='voice' THEN\n    expected_refs=expected_refs||(expected_content->'representative_refs');\n    SELECT count(DISTINCT ROW(ref->>'id',ref->>'version',ref->>'line'))\n     INTO sample_count FROM jsonb_array_elements(expected_refs) ref;\n    expected_content=expected_content||jsonb_build_object('sample_size',sample_count);\n   ELSIF confirmed_item->>'kind'='competitor' THEN\n    SELECT expected_refs||coalesce(jsonb_agg(entry->'source_ref' ORDER BY ordinality), '[]'::jsonb)\n     INTO expected_refs FROM jsonb_array_elements(\n      (expected_content->'metrics')||(expected_content->'features')||(expected_content->'prices'))\n      WITH ORDINALITY refs(entry,ordinality)\n      WHERE jsonb_typeof(entry->'source_ref')='object';\n   END IF;\n   IF r.operation='category.knowledge.promote' THEN\n    expected_refs='[]'::jsonb;\n    IF NEW.version<>1 OR NEW.action<>'add' OR confirmed_proof.subject_type<>'proposal'\n     OR confirmed_proof.subject_id IS DISTINCT FROM (confirmed_item->>'source_proposal_id')::uuid\n     OR confirmed_proof.revision IS DISTINCT FROM\n        (confirmed_item->>'source_proposal_revision')::integer\n     OR (confirmed_item->>'deidentified_confirmed')::boolean IS DISTINCT FROM true THEN\n     RAISE EXCEPTION 'promoted knowledge differs from confirmed source' USING ERRCODE='23514';\n    END IF;\n   ELSE\n    IF (NEW.version=1 AND (confirmed_item->>'supersedes' IS NOT NULL\n         OR confirmed_proof.subject_type<>'category'\n         OR confirmed_proof.subject_id<>NEW.category_id))\n     OR (NEW.version>1 AND (\n         (confirmed_item->'supersedes'->>'lineage_id')::uuid IS DISTINCT FROM NEW.lineage_id\n         OR (confirmed_item->'supersedes'->>'expected_version')::integer\n            IS DISTINCT FROM NEW.version-1\n         OR confirmed_proof.subject_type<>'category_knowledge'\n         OR confirmed_proof.subject_id<>NEW.lineage_id OR confirmed_proof.revision<>NEW.version-1)) THEN\n     RAISE EXCEPTION 'knowledge supersession differs from confirmation' USING ERRCODE='23514';\n    END IF;\n   END IF;\n   IF NEW.kind IS DISTINCT FROM confirmed_item->>'kind'\n    OR NEW.content IS DISTINCT FROM expected_content OR NEW.source_refs IS DISTINCT FROM expected_refs\n    OR to_jsonb(NEW.regions) IS DISTINCT FROM coalesce(confirmed_item->'regions','[]'::jsonb)\n    OR NEW.withdraw_reason IS NOT NULL THEN\n    RAISE EXCEPTION 'knowledge content differs from confirmation' USING ERRCODE='23514';\n   END IF;\n  END IF;\n END IF;\n IF NEW.origin='human' OR (NEW.origin='imported' AND r.operation='category.create') THEN\n  IF NEW.writer_id<>r.actor_id OR r.actor_id<>r.requester_id\n   OR NEW.run_id IS NOT NULL OR NEW.confirmed_by IS NOT NULL\n   OR NEW.prepared_candidate_id IS NOT NULL OR r.agent_run_id IS NOT NULL\n   OR (confirmation_required AND (\n    confirmed_proof.snapshot->'payload'->>'prepared_by_run_id' IS NOT NULL\n    OR confirmed_proof.snapshot->'payload'->>'candidate_digest' IS NOT NULL))\n   OR NOT EXISTS(SELECT 1 FROM principals p WHERE p.tenant_id=NEW.tenant_id\n    AND p.id=NEW.writer_id AND p.kind='human') THEN\n   RAISE EXCEPTION 'material human provenance mismatch' USING ERRCODE='23514';\n  END IF;\n ELSIF NEW.origin='ai_draft' THEN\n  SELECT * INTO STRICT ar FROM agent_runs WHERE tenant_id=NEW.tenant_id AND id=NEW.run_id;\n  IF ar.category_id IS DISTINCT FROM NEW.category_id OR ar.writer_id<>NEW.writer_id\n   OR ar.requester_id<>r.requester_id OR ar.reverted_at IS NOT NULL OR ar.state='cancelled'\n   OR r.agent_run_id IS DISTINCT FROM ar.id OR ar.product_id IS NOT NULL\n   OR NOT EXISTS(SELECT 1 FROM principals p WHERE p.tenant_id=NEW.tenant_id\n    AND p.id=NEW.writer_id AND p.kind='agent') THEN\n   RAISE EXCEPTION 'material AI provenance mismatch' USING ERRCODE='23514';\n  END IF;\n  IF r.operation='category.knowledge.add' AND ar.private_context THEN\n   RAISE EXCEPTION 'private run cannot add shared knowledge' USING ERRCODE='23514';\n  END IF;\n  IF NEW.confirmed_by IS NULL THEN\n   IF r.operation<>'category.knowledge.add' OR r.actor_id<>ar.writer_id\n    OR NEW.prepared_candidate_id IS NOT NULL\n    OR (NEW.version>1 AND (prior.origin<>'ai_draft' OR prior.confirmed_by IS NOT NULL))\n    OR NOT EXISTS(SELECT 1 FROM agent_tool_calls tc WHERE tc.tenant_id=NEW.tenant_id\n     AND tc.run_id=ar.id AND tc.receipt_id=r.id AND tc.state='completed'\n     AND tc.execution_binding->>'operation'=r.operation) THEN\n    RAISE EXCEPTION 'material T0 requires its trusted call' USING ERRCODE='23514';\n   END IF;\n  ELSE\n   SELECT * INTO STRICT pc FROM proposal_prepared_candidates WHERE tenant_id=NEW.tenant_id\n    AND id=NEW.prepared_candidate_id;\n   IF NEW.confirmed_by<>r.actor_id OR r.actor_id<>r.requester_id\n    OR pc.category_id<>NEW.category_id OR pc.run_id<>ar.id OR pc.writer_id<>ar.writer_id\n    OR pc.requester_id<>r.requester_id OR pc.operation<>r.operation\n    OR (confirmed_proof.snapshot->'payload'-ARRAY['prepared_by_run_id','candidate_digest'])\n       IS DISTINCT FROM pc.payload\n    OR confirmed_proof.snapshot->'payload'->>'prepared_by_run_id' IS DISTINCT FROM ar.id::text\n    OR confirmed_proof.snapshot->'payload'->>'candidate_digest' IS DISTINCT FROM pc.candidate_digest\n    OR (pc.execution_binding->'model'->>'cancel_epoch')::integer IS DISTINCT FROM ar.cancel_epoch\n    OR NOT EXISTS(SELECT 1 FROM principals p WHERE p.tenant_id=NEW.tenant_id\n     AND p.id=NEW.confirmed_by AND p.kind='human') THEN\n    RAISE EXCEPTION 'material candidate confirmation mismatch' USING ERRCODE='23514';\n   END IF;\n  END IF;\n ELSE\n  RAISE EXCEPTION 'material import requires a registered import path' USING ERRCODE='23514';\n END IF;\n RETURN NULL;\nEND $function$\n",)
